#Insérer une case à une position donnée

from numpy import *

t = array([int] * 20)

def Saisie():
    b = False
    while not (b):
        n = int(input("Donner le nombre des cases: "))
        b = 5 <= n <= 20
    return n

def Remplir(n):
    for i in range(n):
        t[i] = int(input("t[" + str(i) + "] = "))

def insérer(t, n):
    b = False
    while not b:
        p = int(input("Donner la position de la case à insérer: "))
        b = 0 <= p <= n
    x = int(input("Donner l'élément à insérer: "))
    n += 1
    for i in range(n - 1, p, -1):
        t[i] = t[i - 1]
    t[p] = x
    return n

def Afficher(t, n):
    for i in range(n):
        print(t[i])

